import struct, zlib, hashlib, os
TYPES = {1:'commit',2:'tree',3:'blob',4:'tag'}
def read_idx(idx_path):
    idx = open(idx_path,'rb').read()
    assert idx[:4] == b'\xfftOc'
    n = struct.unpack('>I', idx[8+255*4:8+256*4])[0]
    off = 8+256*4
    shas = [idx[off+i*20:off+i*20+20].hex() for i in range(n)]
    off += n*20
    crcs = [struct.unpack('>I', idx[off+i*4:off+i*4+4])[0] for i in range(n)]
    off += n*4
    offs = [struct.unpack('>I', idx[off+i*4:off+i*4+4])[0] for i in range(n)]
    return list(zip(offs, shas, crcs))
def read_hdr(data, p):
    c = data[p]; t = (c>>4)&7; size = c&15; shift=4; p+=1
    while c & 0x80:
        c = data[p]; size |= (c&0x7f)<<shift; shift+=7; p+=1
    base=None
    if t==6:
        c=data[p]; p+=1; bo = c&0x7f
        while c&0x80:
            c=data[p]; p+=1; bo = ((bo+1)<<7) | (c&0x7f)
        base = bo
    elif t==7:
        base = data[p:p+20].hex(); p+=20
    return t,size,base,p
def varint(buf, p):
    v=0; shift=0
    while True:
        c=buf[p]; p+=1; v |= (c&0x7f)<<shift; shift+=7
        if not c&0x80: break
    return v,p
def apply_delta(base, delta):
    p=0
    bsize,p = varint(delta,p); tsize,p = varint(delta,p)
    assert bsize==len(base), (bsize,len(base))
    out=bytearray()
    while p<len(delta):
        c=delta[p]; p+=1
        if c&0x80:
            off=0; size=0
            if c&0x01: off|=delta[p]; p+=1
            if c&0x02: off|=delta[p]<<8; p+=1
            if c&0x04: off|=delta[p]<<16; p+=1
            if c&0x08: off|=delta[p]<<24; p+=1
            if c&0x10: size|=delta[p]; p+=1
            if c&0x20: size|=delta[p]<<8; p+=1
            if c&0x40: size|=delta[p]<<16; p+=1
            if size==0: size=0x10000
            out += base[off:off+size]
        elif c:
            out += delta[p:p+c]; p+=c
        else:
            raise ValueError('bad delta op')
    assert len(out)==tsize
    return bytes(out)
class Pack:
    def __init__(self, pack_path, idx_path, fallback=None):
        self.data = open(pack_path,'rb').read()
        self.entries = sorted(read_idx(idx_path))
        self.by_off = {o:(s,c) for o,s,c in self.entries}
        self.by_sha = {s:(o,c) for o,s,c in self.entries}
        self.fallback = fallback  # callable sha -> (type, content) or None
        self.cache = {}
    def entry_end(self, off):
        offs = [o for o,_,_ in self.entries]
        import bisect
        i = bisect.bisect_right(offs, off)
        return offs[i] if i < len(offs) else len(self.data)-20
    def raw(self, off):
        t,size,base,p = read_hdr(self.data, off)
        end = self.entry_end(off)
        return t,size,base,self.data[p:end]
    def get_by_off(self, off):
        if off in self.cache: return self.cache[off]
        t,size,base,comp = self.raw(off)
        if comp[:1] != b'\x78':
            raise IOError('zeroed entry at %d (%s)' % (off, self.by_off[off][0]))
        d = zlib.decompressobj(); body = d.decompress(comp)
        if len(body)!=size: raise IOError('bad size at %d'%off)
        if t in (1,2,3,4):
            res = (TYPES[t], body)
        elif t==6:
            boff = off-base
            try:
                bt, bbody = self.get_by_off(boff)
            except IOError:
                bsha = self.by_off[boff][0]
                fb = self.fallback(bsha) if self.fallback else None
                if fb is None: raise IOError('base %s at %d unavailable' % (bsha, boff))
                bt,bbody = fb
            res = (bt, apply_delta(bbody, body))
        elif t==7:
            fb = None
            if base in self.by_sha:
                try: fb = self.get_by_off(self.by_sha[base][0])
                except IOError: fb=None
            if fb is None and self.fallback: fb = self.fallback(base)
            if fb is None: raise IOError('ref base %s unavailable' % base)
            res = (fb[0], apply_delta(fb[1], body))
        else:
            raise IOError('bad type')
        self.cache[off]=res
        return res
    def get(self, sha):
        return self.get_by_off(self.by_sha[sha][0])
def obj_sha(t, body):
    return hashlib.sha1(('%s %d\0'%(t,len(body))).encode()+body).hexdigest()
def write_loose(outdir, t, body):
    sha = obj_sha(t, body)
    d = os.path.join(outdir, sha[:2]); os.makedirs(d, exist_ok=True)
    p = os.path.join(d, sha[2:])
    if not os.path.exists(p):
        with open(p,'wb') as f: f.write(zlib.compress(('%s %d\0'%(t,len(body))).encode()+body, 1))
    return sha
def read_loose(objdir, sha):
    p = os.path.join(objdir, sha[:2], sha[2:])
    if not os.path.exists(p): return None
    raw = zlib.decompress(open(p,'rb').read())
    hdr, body = raw.split(b'\x00',1)
    t, size = hdr.decode().split(' ')
    assert int(size)==len(body)
    return (t, body)
