import sys, os, shutil, glob
sys.path.insert(0, '/tmp/tools')
from packlib import *
repo, out = sys.argv[1], sys.argv[2]
objdir = os.path.join(repo,'objects')
outobj = os.path.join(out,'objects')
os.makedirs(os.path.join(outobj,'pack'), exist_ok=True)
# 1. copy loose objects
n=0
for d in glob.glob(os.path.join(objdir,'[0-9a-f][0-9a-f]')):
    for f in os.listdir(d):
        sha = os.path.basename(d)+f
        t,body = read_loose(objdir, sha)
        assert obj_sha(t,body)==sha, sha
        write_loose(outobj, t, body); n+=1
print("loose copied:", n)
# 2. pack2 intact: copy pack+idx
p2 = os.path.join(objdir,'pack','pack-dc1a3d5e56cdb2c83174659a7deaaca10d01e520')
for ext in ('.pack','.idx'):
    shutil.copy(p2+ext, os.path.join(outobj,'pack',os.path.basename(p2)+ext))
pack2 = Pack(p2+'.pack', p2+'.idx')
def fb(sha):
    if sha in pack2.by_sha:
        try: return pack2.get(sha)
        except IOError: return None
    r = read_loose(objdir, sha)
    return r
# 3. pack1 damaged: export readable entries as loose
p1 = os.path.join(objdir,'pack','pack-0edbe236157d7f40502eaa2e054bc68160f770ab')
pack1 = Pack(p1+'.pack', p1+'.idx', fallback=fb)
ok=0; bad=[]
for off,sha,crc in pack1.entries:
    try:
        t,body = pack1.get_by_off(off)
    except IOError as e:
        bad.append((sha, str(e))); continue
    assert obj_sha(t,body)==sha, ('sha mismatch', sha)
    if sha in pack2.by_sha: 
        ok+=1; continue   # already available via pack2
    write_loose(outobj, t, body); ok+=1
print("pack1 exported/available:", ok, "unavailable:", len(bad))
for s,e in bad: print("  UNAVAILABLE", s, e)
# verify pack2 fully readable and sha-correct
for off,sha,crc in pack2.entries:
    t,body = pack2.get_by_off(off); assert obj_sha(t,body)==sha
print("pack2 verified:", len(pack2.entries))
EOF
